actions.script:
const out = ec.service.sync().name('ironstone.commons.DriveServices.list#FolderView').parameters({driveId: driveId || '', path: path || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {fileList: out.fileList, folder: out.folder, drive: out.drive,
    breadcrumbList: out.breadcrumbList, record: out.record, hiddenCount: out.hiddenCount})

const out = ec.service.sync().name('ironstone.commons.DriveServices.get#ItemDetail').parameters({driveId: driveId || '', path: path || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {item: out.item, drive: out.drive, access: out.access, shareList: out.shareList,
    linkList: out.linkList, record: out.record})

const out = ec.service.sync().name('org.moqui.resource.FileServices.get#VersionDiff').parameters({driveId: driveId || '',
    path: path || '', fromVersion: fromVersion || null, toVersion: toVersion || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {diff: out.diff})

const out = ec.service.sync().name('org.moqui.resource.FileServices.get#Activity').parameters({driveId: driveId || '',
    path: path || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {activityList: out.activityList})

const out = ec.service.sync().name('org.moqui.resource.FileServices.get#Preview').parameters({driveId: driveId || '',
    path: path || '', size: Math.max(16, Math.min(Number(size) || 256, 2048))}).call()
if (!ec.message.hasError() && out.previewLocation) ec.web.sendResourceResponse(out.previewLocation, true)
else ec.web.sendJsonResponse({})

const info = ec.service.sync().name('org.moqui.resource.FileServices.get#ResourceInfo').parameters({driveId: driveId || '',
    path: path || '', versionName: versionName || null, opened: true}).call()
const resource = ec.message.hasError() ? null : info.resource
const zip = resource && resource.isDirectory ? ec.service.sync().name('org.moqui.resource.FileServices.download#Zip').parameters({driveId: driveId,
    path: path}).call() : null
if (ec.message.hasError() || !resource) ec.web.sendJsonResponse({})
else if (zip) ec.web.sendResourceResponse(zip.zipLocation, false, zip.zipFilename)
else ec.web.sendResourceResponse(resource.location, String(inline) === 'true' &&
        /^(image\/(png|jpeg|gif|webp|bmp)|application\/pdf|audio\/|video\/)/.test(String(resource.contentType || '')), resource.name)

let paths = []
try { paths = JSON.parse(pathListJson || '[]') } catch (err) { paths = [] }
const zip = ec.service.sync().name('org.moqui.resource.FileServices.download#Zip').parameters({driveId: driveId || '',
    pathList: Array.isArray(paths) ? paths : []}).call()
if (!ec.message.hasError() && zip?.zipLocation) ec.web.sendResourceResponse(zip.zipLocation, false, zip.zipFilename)
else ec.web.sendJsonResponse({})

let names = []
try { names = JSON.parse(nameListJson || '[]') } catch (err) { names = [] }
const out = ec.service.sync().name('ironstone.commons.DriveServices.check#UploadNames').parameters({driveId: driveId || '', path: path || '', nameList: names}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {conflictList: out.conflictList})

const out = ec.service.sync().name('ironstone.commons.DriveServices.upload#Files').parameters({driveId: driveId || '', path: path || '',
    contentFile: contentFile || null, relativePath: relativePath || null, conflictPolicy: conflictPolicy || 'replace', versionNote: versionNote || null}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const infos = [{type: 'success', message: out.message}]
for (const row of Array.from(out.uploadedList || [])) if (row.outcome === 'failed') infos.push({type: 'warning', message: row.name + ': ' + row.error})
ec.web.sendJsonResponse({uploadedList: out.uploadedList, messageInfos: infos})

const out = ec.service.sync().name('org.moqui.resource.FileServices.rename#Resource').parameters({driveId: driveId || '',
    path: path || '', newName: newName || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {newPath: out.newPath, messageInfos: [{type: 'success', message: ec.l10n.localize('Renamed')}]})

let paths = []
try { paths = JSON.parse(pathListJson || '[]') } catch (err) { paths = [] }
const L = (text) => ec.l10n.localize(text)
if (!Array.isArray(paths)) paths = []
const moving = {driveId: driveId || '', pathList: paths, toDriveId: toDriveId || driveId || '', toPath: toPath || '', conflictPolicy: 'keepBoth'}
const rows = mode === 'copy' ? (ec.service.sync().name('org.moqui.resource.FileServices.copy#Resource').parameters(moving).call()?.copiedList || [])
    : (ec.service.sync().name('org.moqui.resource.FileServices.move#Resource').parameters(moving).call()?.movedList || [])
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const done = Array.from(rows).filter((row) => row.outcome === 'moved' || row.outcome === 'copied' || row.outcome === 'unchanged')
const infos = [{type: done.length ? 'success' : 'warning', message: ec.resource.expand(mode === 'copy' ? 'Copied ${count} of ${total}' : 'Moved ${count} of ${total}', '',
    {count: done.length, total: rows.length})}]
for (const row of Array.from(rows)) if (row.outcome === 'failed') infos.push({type: 'warning', message: row.path + ': ' + L(row.error || 'failed')})
ec.web.sendJsonResponse({resultList: rows, messageInfos: infos})

let paths = []
try { paths = JSON.parse(pathListJson || '[]') } catch (err) { paths = [] }
const out = ec.service.sync().name('org.moqui.resource.FileServices.trash#Resource').parameters({driveId: driveId || '',
    pathList: Array.isArray(paths) ? paths : []}).call()
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const trashed = Array.from(out.trashList || []).filter((row) => row.outcome === 'trashed')
const infos = [{type: trashed.length ? 'success' : 'warning', message: trashed.length === 1 ? ec.resource.expand('${name} moved to the trash', '',
    {name: String(trashed[0].path).split('/').pop()}) : ec.resource.expand('${count} items moved to the trash', '', {count: trashed.length})}]
for (const row of Array.from(out.trashList || [])) if (row.outcome === 'failed') infos.push({type: 'warning', message: row.path + ': ' + row.error})
ec.web.sendJsonResponse({trashList: out.trashList, messageInfos: infos})

const out = ec.service.sync().name('org.moqui.resource.FileServices.restore#Resource').parameter('trashId', trashId || '').call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {driveId: out.driveId, path: out.path, messageInfos: [{type: 'success',
    message: ec.resource.expand('${name} restored', '', {name: String(out.path || '').split('/').pop()})}]})

const out = ec.service.sync().name('org.moqui.resource.FileServices.empty#Trash').parameter('driveId', driveId || '').call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {deletedCount: out.deletedCount, messageInfos: [{type: 'success',
    message: ec.resource.expand('Trash emptied: ${count} deleted for good', '', {count: out.deletedCount})}]})

let names = []
try { names = JSON.parse(tagNamesJson || '[]') } catch (err) { names = [] }
const out = ec.service.sync().name('org.moqui.resource.FileServices.set#Tags').parameters({driveId: driveId || '',
    path: path || '', tagNameList: names}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {tagList: out.tagList})

if (!ec.user.isInGroup('ADMIN')) ec.message.addError(ec.l10n.localize('Only an administrator fetches a mirror'))
const access = ec.message.hasError() ? null : ec.service.sync().name('org.moqui.resource.FileServices.get#DriveAccess').parameter('driveId', driveId || '').call()
if (access && (!access.drive || access.level < 1 || !access.drive.repositoryId)) ec.message.addError(ec.l10n.localize('Drive not found'))
if (!ec.message.hasError()) ec.service.sync().name('org.moqui.git.GitServices.fetch#GitRepository').parameter('repositoryId', access.drive.repositoryId).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {messageInfos: [{type: 'success', message: ec.l10n.localize('Fetched')}]})
